args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-remaining-maps/transport');suppressPackageStartupMessages({library(sf);library(ggplot2);library(patchwork);library(grid)})
sf_use_s2(FALSE);set.seed(20261029)
wr<-function(x,p)jsonlite::write_json(x,p,auto_unbox=TRUE,pretty=TRUE,digits=NA)
pts<-function(g,n){q<-st_transform(st_make_valid(st_union(g)),3857);st_transform(st_sample(q,n,exact=TRUE),4326)}
xy<-function(g){d<-as.data.frame(st_coordinates(g));names(d)[1:2]<-c('x','y');d}
edges<-function(n,k=3){d<-as.matrix(dist(n[,c('x','y')]));diag(d)<-Inf;i<-rep(seq_len(nrow(n)),each=k);j<-unlist(lapply(seq_len(nrow(n)),function(j)order(d[j,])[1:k]));z<-unique(data.frame(i=pmin(i,j),j=pmax(i,j)));z$x<-n$x[z$i];z$y<-n$y[z$i];z$xend<-n$x[z$j];z$yend<-n$y[z$j];z}
th<-theme_void(base_family='Arial',base_size=7)+theme(legend.position='bottom',legend.text=element_text(size=7),legend.title=element_text(size=7),plot.title=element_text(size=7,face='bold'),plot.tag=element_text(size=8,face='bold'),strip.text=element_text(size=7),plot.margin=margin(2,2,2,2))
finish<-function(mid,p,stem,width,height,scope,geom,panels){w<-file.path(W,mid);dir.create(w,showWarnings=FALSE);saveRDS(p,file.path(w,'plot.rds'));ggsave(file.path(w,'exploratory.png'),p,width=width,height=height,units='mm',dpi=160,device=ragg::agg_png,bg='white');ragg::agg_png(file.path(w,'grob-measurement.png'),width=width,height=height,units='mm',res=160,background='white');g<-if(inherits(p,'patchwork'))patchworkGrob(p)else ggplotGrob(p);labels<-character();sizes<-numeric();fix<-function(x){if(inherits(x,'text')){x$gp$fontfamily<-'Arial';if(!is.null(x$gp$fontsize)){x$gp$fontsize<-pmax(7,x$gp$fontsize);sizes<<-c(sizes,x$gp$fontsize)};labels<<-c(labels,as.character(x$label))};if(length(x$grobs))x$grobs<-lapply(x$grobs,fix);if(length(x$children))x$children<-do.call(gList,lapply(x$children,fix));x};g<-fix(g);dev.off();saveRDS(g,file.path(w,'composed-vector-grob.rds'));saveRDS(ggplotify::as.ggplot(g)+theme(text=element_text(family='Arial',size=7),plot.margin=margin(0,0,0,0)),file.path(w,'render-object.rds'));wr(list(labels=unique(labels[nzchar(labels)]),point_sizes=sort(unique(sizes))),file.path(w,'text-manifest.json'));wr(list(stem=stem,width_mm=width,height_mm=height,panel_count=panels,simulation=TRUE,seed=20261029,data_origin=paste('User-authorized STRUCTURE PRACTICE ONLY. Fixed-seed synthetic values and positions; not author study data.',scope),geometry_crs=geom,palette='Source-guided categorical or ordered quantitative palette; independent legends preserve distinct meanings.'),file.path(w,'input-qc.json'));cat(mid,'PREPARED\n')}
export<-function(z,stem){write.csv(z,file.path(P,'results/plot_data',paste0(stem,'_20261029.csv')),row.names=FALSE)}
